// Now let's execute the replacement in fileContent.
// We will parse the file using VM, find the questions, replace the matching question properties, and re-serialize or do targeted regex/string replaces.
// Since each question object in fileContent has a known id, let's update them carefully.

const vm = require('vm');
const sandbox = {};
const scriptCode = fileContent.replace(/export const /g, 'var ');
vm.runInNewContext(scriptCode, sandbox);
const questions = sandbox.FOUNDATION_FINANCE_193_QUESTIONS;

let updatedCount = 0;
for (const [idStr, replacement] of Object.entries(REPLACEMENTS)) {
  const id = Number(idStr);
  const q = questions.find(x => x.id === id);
  if (q) {
    Object.assign(q, replacement);
    updatedCount++;
  }
}

console.log(`Updated ${updatedCount} questions in memory.`);

// Now let's serialize FOUNDATION_FINANCE_193_QUESTIONS back into the file.
// Let's locate `export const FOUNDATION_FINANCE_193_QUESTIONS = [` and its matching closing `];`.
const startMarker = 'export const FOUNDATION_FINANCE_193_QUESTIONS = [';
const startIndex = fileContent.indexOf(startMarker);
if (startIndex === -1) {
  console.error('Could not find startMarker!');
  process.exit(1);
}

// Find matching closing bracket for FOUNDATION_FINANCE_193_QUESTIONS
let bracketCount = 0;
let endIndex = -1;
let inString = false;
let stringChar = '';
let inEscape = false;

for (let i = startIndex + startMarker.length - 1; i < fileContent.length; i++) {
  const char = fileContent[i];
  if (inEscape) {
    inEscape = false;
    continue;
  }
  if (char === '\\') {
    inEscape = true;
    continue;
  }
  if (inString) {
    if (char === stringChar) {
      inString = false;
    }
    continue;
  }
  if (char === '"' || char === "'" || char === '`') {
    inString = true;
    stringChar = char;
    continue;
  }
  if (char === '[') {
    bracketCount++;
  } else if (char === ']') {
    bracketCount--;
    if (bracketCount === 0) {
      endIndex = i;
      break;
    }
  }
}

if (endIndex === -1) {
  console.error('Could not find matching closing bracket!');
  process.exit(1);
}

console.log(`Found array range: ${startIndex} to ${endIndex}`);

const formattedQuestions = JSON.stringify(questions, null, 2);
const newFileContent = fileContent.slice(0, startIndex + startMarker.length - 1) +
  formattedQuestions +
  fileContent.slice(endIndex + 1);

fs.writeFileSync(targetFilePath, newFileContent, 'utf8');
console.log('Successfully wrote updated questions to ' + targetFilePath);
